1	'use client'
2	
3	import dynamic from 'next/dynamic'
4	import { useCallback } from 'react'
5	import { useRouter, useSearchParams } from 'next/navigation'
6	import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
7	import { toast } from 'sonner'
8	import { Skeleton } from '@/components/ui/skeleton'
9	import { AppointmentDrawer } from '@/components/appointments/AppointmentDrawer'
10	import type { CalendarBooking } from '@/components/calendar/CalendarView'
11	import { useCalendarDrawer } from '@/hooks/calendar/use-calendar-drawer'
12	
13	// Must be ssr:false — FullCalendar uses browser globals
14	const CalendarView = dynamic(
15	  () =>
16	    import('@/components/calendar/CalendarView').then((mod) => mod.CalendarView),
17	  {
18	    ssr: false,
19	    loading: () => (
20	      <div className="flex-1 p-4 space-y-3">
21	        <div className="flex items-center gap-3">
22	          <Skeleton className="h-9 w-32 rounded-lg" />
23	          <Skeleton className="h-9 w-24 rounded-lg" />
24	          <Skeleton className="h-9 w-24 rounded-lg" />
25	          <div className="ml-auto flex gap-2">
26	            <Skeleton className="h-9 w-9 rounded-lg" />
27	            <Skeleton className="h-9 w-20 rounded-lg" />
28	            <Skeleton className="h-9 w-9 rounded-lg" />
29	          </div>
30	        </div>
31	        <Skeleton className="h-[60vh] w-full rounded-xl" />
32	      </div>
33	    ),
34	  }
35	)
