37	// ── C7: URL search param helpers ────────────────────────────────────────────
38	function parseIds(value: string | null): string[] {
39	  if (!value) return []
40	  return value.split(',').filter(Boolean)
41	}
42	
43	function serializeIds(ids: string[]): string {
44	  return ids.join(',')
45	}
46	
47	export function CalendarPageClient() {
48	  const router = useRouter()
49	  const searchParams = useSearchParams()
50	  const queryClient = useQueryClient()
51	
52	  // ── C7: Lift filter state into URL ─────────────────────────────────────
53	  const filterArtistIds = parseIds(searchParams.get('artists'))
54	  const filterStatuses = parseIds(searchParams.get('statuses'))
55	  const filterServiceIds = parseIds(searchParams.get('services'))
56	
57	  function updateFilters(updates: {
58	    artists?: string[]
59	    statuses?: string[]
60	    services?: string[]
61	  }) {
62	    const next = new URLSearchParams(searchParams.toString())
63	    if (updates.artists !== undefined) {
64	      if (updates.artists.length > 0) {
65	        next.set('artists', serializeIds(updates.artists))
66	      } else {
67	        next.delete('artists')
68	      }
69	    }
70	    if (updates.statuses !== undefined) {
71	      if (updates.statuses.length > 0) {
72	        next.set('statuses', serializeIds(updates.statuses))
73	      } else {
74	        next.delete('statuses')
75	      }
76	    }
77	    if (updates.services !== undefined) {
78	      if (updates.services.length > 0) {
79	        next.set('services', serializeIds(updates.services))
80	      } else {
81	        next.delete('services')
82	      }
83	    }
84	    router.replace(`?${next.toString()}`, { scroll: false })
85	  }
86	
87	  // ── Drawer state ────────────────────────────────────────────────────────
88	  const {
89	    drawerOpen,
90	    setDrawerOpen,
91	    editingId,
92	    defaultStart,
93	    defaultEnd,
94	    openNew,
95	    openEdit,
96	  } = useCalendarDrawer()
97	
98	  const {
99	    data,
100	    isLoading,
101	    error,
102	    refetch,
103	  } = useQuery<{ data: CalendarBooking[]; count: number }>({
104	    queryKey: ['bookings', 'calendar'],
105	    queryFn: async () => {
106	      const res = await fetch('/api/bookings?per_page=500')
107	      if (!res.ok) throw new Error('Failed to fetch bookings')
108	      return res.json() as Promise<{ data: CalendarBooking[]; count: number }>
109	    },
110	  })
111	
112	  const rescheduleMutation = useMutation({
113	    mutationFn: async ({
114	      id,
115	      newStart,
116	      newEnd,
117	    }: {
118	      id: string
119	      newStart: Date
120	      newEnd: Date
121	    }) => {
122	      const durationMs = newEnd.getTime() - newStart.getTime()
123	      const duration_min = Math.round(durationMs / 60000)
124	      const res = await fetch(`/api/bookings/${id}`, {
125	        method: 'PATCH',
126	        headers: { 'Content-Type': 'application/json' },
127	        body: JSON.stringify({
128	          scheduled_at: newStart.toISOString(),
129	          duration_min,
130	        }),
131	      })
132	      if (!res.ok) {
133	        const err = await res.json() as { error?: string }
134	        throw new Error(err.error ?? 'Reschedule failed')
135	      }
136	      return res.json()
137	    },
138	    onSuccess: () => {
139	      void queryClient.invalidateQueries({ queryKey: ['bookings'] })
140	    },
141	  })
142	
143	  const handleReschedule = useCallback(
144	    async (id: string, newStart: Date, newEnd: Date) => {
145	      await rescheduleMutation.mutateAsync({ id, newStart, newEnd })
146	    },
147	    [rescheduleMutation]
148	  )
149	
150	  const bookings = data?.data ?? []
151	  const totalBookings = data?.count ?? 0
152	
153	  return (
154	    <div className="flex flex-col flex-1 overflow-hidden h-full">
155	      <CalendarView
156	        bookings={bookings}
157	        isLoading={isLoading}
158	        error={error ? (error instanceof Error ? error.message : 'Unknown error') : null}
159	        totalBookings={totalBookings}
160	        filterArtistIds={filterArtistIds}
161	        filterStatuses={filterStatuses}
162	        filterServiceIds={filterServiceIds}
163	        onArtistFilterChange={(ids) => updateFilters({ artists: ids })}
164	        onStatusFilterChange={(statuses) => updateFilters({ statuses })}
165	        onServiceFilterChange={(ids) => updateFilters({ services: ids })}
166	        onNewAppointment={openNew}
167	        onEditAppointment={openEdit}
168	        onReschedule={handleReschedule}
169	        onRetry={() => {
170	          void refetch()
171	        }}
172	      />
173	
174	      <AppointmentDrawer
175	        open={drawerOpen}
176	        onOpenChange={setDrawerOpen}
177	        editingId={editingId}
178	        {...(defaultStart !== undefined ? { defaultStart } : {})}
179	        {...(defaultEnd !== undefined ? { defaultEnd } : {})}
180	        onSuccess={() => {
181	          setDrawerOpen(false)
182	          void queryClient.invalidateQueries({ queryKey: ['bookings'] })
183	          toast.success(editingId ? 'Appointment updated' : 'Appointment created')
184	        }}
185	      />
186	    </div>
187	  )
188	}
